#Requires -RunAsAdministrator
[CmdletBinding()]param([Parameter(Mandatory)][ValidatePattern('^[^\\@]+$')][string]$ChildUser,[switch]$RemoveData)
$ErrorActionPreference='Stop';$admin="$env:ProgramFiles\ParentControl Remote\ParentControl.Admin.exe";if(Test-Path $admin){& $admin emergency-unlock $ChildUser};Stop-Service ParentControlRemote -Force -ErrorAction SilentlyContinue;sc.exe delete ParentControlRemote|Out-Null;Remove-NetFirewallRule -DisplayName 'ParentControl Remote (Tailscale)' -ErrorAction SilentlyContinue;Write-Host 'Dienst entfernt. Programmdateien können nach Dienstende gelöscht werden.';if($RemoveData){$exact=[IO.Path]::GetFullPath("$env:ProgramData\ParentControlRemote");if($exact -eq [IO.Path]::GetFullPath("$env:ProgramData\ParentControlRemote")){Remove-Item -LiteralPath $exact -Recurse -Force}}
